import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

export type Person = { id: number; sheetId: string; name: string; grade: Grade };
export type PersonInput = { name: string; grade: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function listPeople(sheetId: string): Promise<Person[]> {
  return getJson<Person[]>(base(sheetId));
}

/** Add a person; refused (rejects) when the name is empty or already in use on the sheet. */
export function addPerson(sheetId: string, by: string, input: PersonInput): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** Edit a person; refused (rejects) like an add. */
export function updatePerson(sheetId: string, by: string, id: number, input: PersonInput): Promise<Person> {
  return putJson<Person>(`${base(sheetId)}/${id}?by=${encodeURIComponent(by)}`, input);
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { People } from './People';

export const contribution = SheetBody.fill({ order: 10, Component: People });
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { GRADES, addPerson, listPeople, peopleKey, updatePerson, type Person, type PersonInput } from './api';

const EMPTY: PersonInput = { name: '', grade: 'A' };

/** The people on the sheet: a form that adds a person or edits one, and the list in added order. */
export function People({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const [form, setForm] = useState<PersonInput>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);

  const save = useMutation({
    mutationFn: (v: { id: number | null; input: PersonInput }) =>
      v.id === null ? addPerson(sheetId, user, v.input) : updatePerson(sheetId, user, v.id, v.input),
    onSuccess: () => {
      setForm(EMPTY);
      setEditing(null);
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (p: Person) => {
    setForm({ name: p.name, grade: p.grade });
    setEditing(p.id);
    save.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  return (
    <section>
      <h3>People</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          save.reset();
          save.mutate({ id: editing, input: form });
        }}
      >
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select data-testid="person-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && <span data-testid="person-form-error">A person needs a name not already in use.</span>}
      </form>
      {people.isError && <p data-testid="people-error">The people could not be loaded.</p>}
      <table>
        <tbody>
          {(people.data ?? []).map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { postJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-MM-dd): every date decision and default uses it. */
export type Sheet = { id: string; createdBy: string; today: string };

/** Load a sheet by id; the server starts it empty the first time the id is used. */
export function openSheet(id: string, by: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/open?by=${encodeURIComponent(by)}`,
    {},
  );
}

/** Change the sheet's today; refused (rejects) when it is not a date. */
export function setSheetToday(id: string, by: string, today: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/today?by=${encodeURIComponent(by)}`,
    { today },
  );
}

/** Every query about a sheet lives under this key, so loading it again re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { setSheetToday, sheetKey, type Sheet } from './api';

/** The sheet's today, shown and changeable. Every date on the sheet goes by it. */
export function SheetToday({ sheet, user }: { sheet: Sheet; user: string }) {
  const queryClient = useQueryClient();
  const [date, setDate] = useState('');
  const save = useMutation({
    mutationFn: (today: string) => setSheetToday(sheet.id, user, today),
    onSuccess: (updated) => {
      // Everything under the sheet may depend on its today: re-read it all.
      queryClient.setQueryData(sheetKey(sheet.id), updated);
      queryClient.invalidateQueries({
        queryKey: sheetKey(sheet.id),
        predicate: (q) => q.queryKey.length > 2,
      });
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        save.mutate(date.trim());
      }}
    >
      Today <span data-testid="sheet-today">{sheet.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          save.reset();
        }}
      />{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      {save.isError && <span data-testid="sheet-error">That is not a date.</span>}
    </form>
  );
}

