  const c = claimRow(page, claimId);
  const lines = c.getByTestId('claim-lines-line');
  const was = await lines.count();
  await c.getByTestId('claim-line-label').fill(f.label);
  await c.getByTestId('claim-line-qty').fill(f.qty);
